/**
 * Modal state for the wizard install step, plus the force-wizard experiment's escape hatch: in the
 * test arm, manual setup and Skip stay hidden until the hatch reveals — after a wall-clock timeout,
 * or as soon as a wizard run hard-fails, so users the agent can't help aren't dead-ended.
 */
export const wizardInstallStepLogic = kea<wizardInstallStepLogicType>([
    path(['scenes', 'onboarding', 'wizardInstallStepLogic']),
    connect(() => ({
        actions: [
            onboardingEventUsageLogic,
            [
                'reportOnboardingInstallEscapeHatchShown',
                'reportOnboardingInstallEscapeHatchClicked',
                'reportOnboardingManualSetupOpened',
                'reportContextOnboardingCloudRunCompleted',
            ],
        ],
    })),
    actions({
        setManualModalOpen: (open: boolean) => ({ open }),
        setSdkInstructionsOpen: (open: boolean) => ({ open }),
        armEscapeHatch: () => ({ deadline: Date.now() + ESCAPE_HATCH_TIMEOUT_MS }),
        disarmEscapeHatch: true,
        revealEscapeHatch: (trigger: EscapeHatchTrigger) => ({ trigger }),
        clickEscapeHatch: true,
    }),
    reducers({
        manualModalOpen: [
            false,
            {
                setManualModalOpen: (_, { open }) => open,
            },
        ],
        sdkInstructionsOpen: [
            false,
            {
                setSdkInstructionsOpen: (_, { open }) => open,
            },
        ],
        escapeHatchArmed: [
            false,
            {
                armEscapeHatch: () => true,
                disarmEscapeHatch: () => false,
            },
        ],
        // The wall-clock deadline lives in a reducer, NOT `cache`: kea keeps a built logic's cache
        // across remounts, so a cached deadline from an earlier visit would reveal the hatch
        // instantly on a revisit instead of after a fresh window. First arm wins while mounted.
        escapeHatchDeadline: [
            null as number | null,
            {
                armEscapeHatch: (state, { deadline }) => state ?? deadline,
                disarmEscapeHatch: () => null,
            },
        ],
        // First trigger wins, so the reveal reason reported below stays the reason the user saw.
        escapeHatchTrigger: [
            null as EscapeHatchTrigger | null,
            {
                revealEscapeHatch: (state, { trigger }) => state ?? trigger,
            },
        ],
    }),
    selectors({
        escapeHatchRevealed: [
            (s) => [s.escapeHatchTrigger],
            (escapeHatchTrigger: EscapeHatchTrigger | null): boolean => escapeHatchTrigger !== null,
        ],
    }),
    listeners(({ actions, values, cache, selectors }) => ({
        armEscapeHatch: () => {
            if (values.escapeHatchRevealed) {
                return
            }
            cache.disposables.add(() => {
                // Read the deadline at setup time: disposables pause on tab-hide and re-run setup
                // on show, and users alt-tab to a terminal constantly on this step — a bare
                // setTimeout would restart the countdown on every return instead of scheduling
                // the remainder against the stored wall-clock deadline.
                const deadline = values.escapeHatchDeadline
                if (deadline === null) {
                    return () => {}
                }
                const timerId = window.setTimeout(
                    () => actions.revealEscapeHatch('timeout'),
                    Math.max(0, deadline - Date.now())
                )
                return () => clearTimeout(timerId)
            }, 'escapeHatchTimeout')
        },
        disarmEscapeHatch: () => {
            cache.disposables.dispose('escapeHatchTimeout')
        },
        revealEscapeHatch: ({ trigger }, _breakpoint, _action, previousState) => {
            // The reducer keeps the first trigger; only the null → trigger transition reports.
            if (selectors.escapeHatchTrigger(previousState) !== null) {
                return
            }
            cache.disposables.dispose('escapeHatchTimeout')
            actions.reportOnboardingInstallEscapeHatchShown(trigger)
        },
        clickEscapeHatch: () => {
            const trigger = values.escapeHatchTrigger
            if (trigger === null) {
                return
            }
            actions.reportOnboardingInstallEscapeHatchClicked(trigger)
            actions.reportOnboardingManualSetupOpened('escape_hatch')
            actions.setManualModalOpen(true)
        },
        // Hard wizard failures reveal the hatch immediately so a user whose run just died isn't
        // left waiting out the timer. Armed-only: the control arm never arms, so nothing leaks.
        reportContextOnboardingCloudRunCompleted: ({ status }) => {
            if (values.escapeHatchArmed && status === 'failed') {
                actions.revealEscapeHatch('cloud_run_failed')
            }
        },
        [wizardCloudRunLogic.actionTypes.startCloudRunFailure]: () => {
            if (values.escapeHatchArmed) {
                actions.revealEscapeHatch('cloud_run_failed')
            }
        },
        [eventUsageLogic.actionTypes.reportWizardSyncSessionFinished]: (payload: { outcome?: string }) => {
            if (values.escapeHatchArmed && payload?.outcome === 'error') {
                actions.revealEscapeHatch('local_session_error')
            }
        },
    })),
])
